def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    templates = []
    for r, row in enumerate(grid):
        runs = []
        start = None
        for c in range(w + 1):
            v = row[c] if c < w else 0
            if v and start is None:
                start = c
            elif not v and start is not None:
                runs.append(row[start:c])
                start = None
        templates.extend(seq for seq in runs if len(seq) > 1)
    # A singleton marker is expanded using the matching position in its source run.
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 0 or (c > 0 and row[c - 1] != 0) or (c + 1 < w and row[c + 1] != 0):
                continue
            choices = [seq for seq in templates if v in seq]
            if not choices:
                continue
            seq = min(choices, key=len)
            start = c - seq.index(v)
            for j, x in enumerate(seq):
                if 0 <= start + j < w:
                    out[r][start + j] = x
    return out
